const { accessSync, constants } = await import('node:fs');
const filePath = process.env.FILE_PATH;
if (!filePath) { throw new Error('FILE_PATH env var not set'); }
try { accessSync(filePath, constants.R_OK); } catch (e) { throw new Error('File not accessible: ' + e.message); }
globalThis.filePath = filePath;

const { readFileSync } = await import('node:fs');
const raw = readFileSync(globalThis.filePath, 'utf8');
if (!raw) { throw new Error('File is empty'); }
globalThis.decoded = raw.trim();
